}
for (const id of ids) {
  const result = spawnSync(
    join(workspace, 'node_modules/.bin/tsc'),
    ['-p', join(lab, 'roots', id, 'libs/compiler/tsconfig.lib.json')],
    { cwd: workspace, encoding: 'utf8' },
