    await cdp.send('HeapProfiler.collectGarbage');
    data.heapMiB =
      (await cdp.send('Runtime.getHeapUsage')).usedSize / 1024 / 1024;
    data.actions = Object.fromEntries(
      Object.entries(samples).map(([name, values]) => [name, median(values)]),
